/**
 * @name Command injection via subprocess with shell=True
 * @description Detects subprocess calls with shell=True where user input may flow into the command
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from sys.argv
    exists(DataFlow::Node argvAccess |
      argvAccess = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() and
      source = argvAccess
    )
    or
    // Function parameters as potential sources
    source instanceof DataFlow::ParameterNode
    or
    // Remote flow sources (HTTP requests, etc.)
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection: user input flows to subprocess call with shell=True $@.", source.getNode(), "from here"

/**
 * @name Code injection via eval/exec
 * @description User input flows to eval, exec, or compile functions
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from sys.argv
    exists(DataFlow::Node argvAccess |
      argvAccess = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() and
      source = argvAccess
    )
    or
    // Function parameters as potential sources
    source instanceof DataFlow::ParameterNode
    or
    // Remote flow sources
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // eval, exec, compile calls
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection: user input flows to dangerous function $@.", source.getNode(), "from here"
